#include <cstdio>
using namespace std;
const int N = 1e5 + 5;
int n, m, deg[N];
long long ans;
int main() {
    scanf("%d%d", &n, &m);
    while (m--) {
        int u, v;
        scanf("%d%d", &u, &v);
        deg[u]++;
        deg[v]++;
    }
    for (int i = 1; i <= n; i++)
        ans += 1ll * deg[i] * (deg[i] - 1) / 2;
    printf("%lld\n", ans);
    return 0;
}

#include <cstdio>
#include <algorithm>
using namespace std;
const int N = 105;
const int C = 505;
const int D = N * C * 2;
int n;
int f[D];
int main() {
    scanf("%d", &n);
    for (int i = 0; i < D; i++)
        f[i] = -1e9;
    f[N * C] = 0;
    while (n--) {
        int a, b;
        scanf("%d%d", &a, &b);
        int x = a + b, y = a - b;
        if (y <= 0) {
            for (int i = -y; i < D; i++)
                f[i + y] = max(f[i + y], f[i] + x);
        } else {
            for (int i = D - y - 1; i; i--)
                f[i + y] = max(f[i + y], f[i] + x);
        }
    }
    printf("%d\n", f[N * C]);
    return 0;
}
